package dev.jobflow.api; import dev.jobflow.api.AuthDtos.*; import dev.jobflow.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;} @PostMapping("/register") ResponseEntity<TokenResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(auth.register(r));}@PostMapping("/login") TokenResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);}}
